contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint amount) public payable {
        require(member != address(0), "member");

        address poolFactory = address(0);
        address pool = address(0);
        uint amountSent = 0;

        (bool factoryOk, bytes memory factoryData) = address(c).staticcall(
            abi.encodeWithSignature("BASE()")
        );
        if (factoryOk && factoryData.length >= 32) {
            address base = abi.decode(factoryData, (address));
            if (base != address(0)) {
                (bool daoOk, bytes memory daoData) = base.staticcall(
                    abi.encodeWithSignature("DAO()")
                );
                if (daoOk && daoData.length >= 32) {
                    address dao = abi.decode(daoData, (address));
                    if (dao != address(0)) {
                        (bool pfOk, bytes memory pfData) = dao.staticcall(
                            abi.encodeWithSignature("POOLFACTORY()")
                        );
                        if (pfOk && pfData.length >= 32) {
                            poolFactory = abi.decode(pfData, (address));
                            if (poolFactory != address(0)) {
                                (bool poolOk, bytes memory poolData) = poolFactory.staticcall(
                                    abi.encodeWithSignature("getPool(uint256)", 0)
                                );
                                if (poolOk && poolData.length >= 32) {
                                    pool = abi.decode(poolData, (address));
                                }
                            }
                        }
                    }
                }
            }
        }

        if (pool != address(0)) {
            amountSent = amount;
            uint256 poolBalanceBefore = iBEP20(pool).balanceOf(address(c));
            uint256 minted = c.mintSynth(member, amountSent);
            uint256 poolBalanceAfter = iBEP20(pool).balanceOf(address(c));
            assert(minted == amountSent);
            assert(poolBalanceAfter == poolBalanceBefore + amountSent);
        } else {
            uint256 poolBalanceBefore = 0;
            uint256 minted = 0;
            bool reverted = false;
            amountSent = amount;
            try c.mintSynth(member, amountSent) returns (uint256 m) {
                minted = m;
            } catch {
                reverted = true;
            }
            assert(reverted || minted == amountSent);
            assert(reverted || poolBalanceBefore == 0);
        }
    }

    receive() external payable {}
}

