contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient zero");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(address(this)) == senderBefore - amount);
            assert(c.balanceOf(recipient) == recipientBefore + amount);
            assert(c.totalSupply() == supplyBefore);
        } else {
            assert(c.balanceOf(address(this)) == senderBefore);
            assert(c.balanceOf(recipient) == recipientBefore);
            assert(c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

