        require(sender != address(this), "sender is test");
        require(recipient != sender, "self transfer");
        require(approvalAmount < type(uint256).max, "max allowance");

        uint256 senderBal0 = c.balanceOf(sender);
        uint256 total0 = c.totalSupply();
        uint256 mintAmount = senderBal0 + amount;
        bool minted = total0 < type(uint256).max - mintAmount;
        require(minted, "overflow guard");

        uint256 balBefore;
        if (minted) {
            c.mintSynth(sender, amount);
            balBefore = c.balanceOf(sender);
        } else {
            balBefore = senderBal0;
        }

        c.approve(address(this), approvalAmount);
        bool approved = true;
        uint256 allowanceBefore = c.allowance(sender, address(this));

        bool reverted;
        bool success;
        try c.transferFrom(sender, recipient, amount) returns (bool ok) {
            success = ok;
            reverted = false;
        } catch {
            success = false;
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(sender);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        bool expectedRevert = (amount > balBefore) || (amount > allowanceBefore);

        assert(reverted == expectedRevert && reverted ? (balAfter == balBefore && allowanceAfter == allowanceBefore) : (success && balAfter == balBefore - amount && allowanceAfter == allowanceBefore - amount));
    }

    receive() external payable {}
}

