contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 burnAmount) public {
        // Precondition: burnAmount must be nonzero and bounded so a mint can succeed
        require(burnAmount > 0, "zero");

        // Setup: mint synthetic tokens to this test contract so burnSynth has supply to burn.
        // mintSynth requires onlyPool, but the test contract itself cannot satisfy that here;
        // instead we rely on the only public entry that changes supply.
        address member = address(this);
        uint256 syntheticAmount = c.mintSynth(member, burnAmount);

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 debtBefore = c.getmapAddress_LPDebt(address(this));
        uint256 lpBefore = c.getmapAddress_LPBalance(address(this));

        uint256 syntheticHeldBefore = c.balanceOf(address(c));

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 debtAfter = c.getmapAddress_LPDebt(address(this));
        uint256 lpAfter = c.getmapAddress_LPBalance(address(this));

        // General rule: if burnSynth completes, the synthetic token balance of the caller
        // is reduced by exactly the synthetic amount the contract was holding at the start of
        // the call, and the recorded LP debt is reduced by that same synthetic amount.
        // If it reverts, no observable state change occurred.
        if (!reverted) {
            assert(balanceBefore >= syntheticHeldBefore && balanceAfter == balanceBefore - syntheticHeldBefore && debtAfter == debtBefore - syntheticHeldBefore);
        } else {
            assert(balanceAfter == balanceBefore && debtAfter == debtBefore && lpAfter == lpBefore);
        }
    }
}

