    constructor(C _c) { c = _c; }

    function run(address spender, address recipient, uint256 amount) public payable {
        address sender = address(this);

        c.approve(spender, amount);

        uint256 allowanceBefore = c.allowance(sender, spender);
        uint256 recipientBalanceBefore = c.balanceOf(recipient);

        c.transferFrom(sender, recipient, amount);

        uint256 allowanceAfter = c.allowance(sender, spender);
        uint256 recipientBalanceAfter = c.balanceOf(recipient);

        if (allowanceBefore < type(uint256).max) {
            assert(allowanceAfter == allowanceBefore - amount);
        } else {
            assert(allowanceAfter == allowanceBefore);
        }
        assert(recipientBalanceAfter == recipientBalanceBefore + amount);
    }

    receive() external payable {}
}

