contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");

        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 totalSupplyBefore = c.totalSupply();

        require(senderBalBefore >= amount, "insufficient balance");

        bool reverted;
        try c.transfer(recipient, amount) returns (bool ok) {
            reverted = false;
            assert(ok);
        } catch {
            reverted = true;
        }

        assert(reverted || (
            c.balanceOf(address(this)) == senderBalBefore - amount &&
            c.balanceOf(recipient) == recipientBalBefore + amount &&
            c.totalSupply() == totalSupplyBefore
        ));
    }

    receive() external payable {}
}

