contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");

        // Setup: mint tokens to this contract so it can transfer them.
        // The public surface does not expose a mint function, so if balance is
        // insufficient the transfer will revert; in that case the assert below
        // only checks the revert-consistent branch.
        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 totalSupplyBefore = c.totalSupply();

        bool ok;
        try c.transfer(recipient, amount) returns (bool _ok) {
            ok = _ok;
        } catch {
            ok = false;
        }

        assert(ok == (senderBalBefore >= amount && recipient != address(this)));
        if (ok) {
            assert(c.balanceOf(address(this)) == senderBalBefore - amount);
            assert(c.balanceOf(recipient) == recipientBalBefore + amount);
            assert(c.totalSupply() == totalSupplyBefore);
        } else {
            assert(c.balanceOf(address(this)) == senderBalBefore);
            assert(c.balanceOf(recipient) == recipientBalBefore);
            assert(c.totalSupply() == totalSupplyBefore);
        }
    }

    receive() external payable {}
}

