    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 addedValue) public {
        require(spender != address(0), "!spender");
        require(addedValue != 0, "!addedValue");

        uint256 beforeAllowance = c.allowance(address(this), spender);
        require(beforeAllowance < type(uint256).max - addedValue, "would-overflow-or-max");

        c.increaseAllowance(spender, addedValue);

        uint256 afterAllowance = c.allowance(address(this), spender);

        assert(afterAllowance == beforeAllowance + addedValue);
    }

    receive() external payable {}
}

