contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 startAllowance, uint256 subtractedValue) public {
        require(spender != address(0), "spender zero");
        require(startAllowance >= subtractedValue, "subtract too large");

        c.approve(spender, startAllowance);
        uint256 beforeAllowance = c.allowance(address(this), spender);
        require(beforeAllowance == startAllowance, "approve did not set allowance");

        bool reverted;
        bool returned;
        try c.decreaseAllowance(spender, subtractedValue) returns (bool r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        assert(!reverted && returned && afterAllowance == beforeAllowance - subtractedValue);
    }

    receive() external payable {}
}

