contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 approved) public {
        sender = address(uint160(uint256(keccak256(abi.encodePacked(sender)))) | 1);
        recipient = address(uint160(uint256(keccak256(abi.encodePacked(recipient)))) | 1);

        c.approve(recipient, approved);

        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderBalAfter = c.balanceOf(sender);
        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        if (reverted) {
            assert(
                amount > senderBalBefore ||
                (allowanceBefore != type(uint256).max && allowanceBefore < amount)
            );
        } else {
            assert(
                senderBalAfter == senderBalBefore - amount &&
                recipientBalAfter == recipientBalBefore + amount &&
                allowanceAfter == (allowanceBefore == type(uint256).max ? type(uint256).max : allowanceBefore - amount)
            );
        }
    }

    receive() external payable {}
}

