        require(cSynthBefore >= synthHeldByC, "c synth balance too low");
        require(debtBeforeActual >= cSynthBefore, "debt below synth balance");

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 debtAfter = c.mapSynth_LPDebt(pool);

        assert(
            reverted ||
            debtAfter <= debtBeforeActual &&
            debtBeforeActual - debtAfter == cSynthBefore
        );
    }

    receive() external payable {}
}

